manifests.destinations.yaml:
destinations:
  mysql_employees:
    type: mysql
    connection:
      host: ${ENV:MYSQL_HOST}
      port: ${ENV:MYSQL_PORT}
      user: ${ENV:MYSQL_USER}
      password: ${ENV:MYSQL_PASSWORD}
      database: ${ENV:MYSQL_DATABASE}
    load:
      table: employees
      mode: append

manifests.sources.yaml:
sources:
  mysql_employees:
    type: mysql
    connection:
      host: ${ENV:MYSQL_HOST}
      port: ${ENV:MYSQL_PORT}
      user: ${ENV:MYSQL_USER}
      password: ${ENV:MYSQL_PASSWORD}
      database: ${ENV:MYSQL_DATABASE}
    extract:
      table: employees
      batch_size: 100

